/**
 * Apostolul și Evanghelia de la Liturghie, pe zile, și textul lor.
 *
 * data/lecturi.json and data/biblia-nt.json are copies of the app's
 * assets/data/lecturi.json (generated by troita's tool/lectionary.py) and
 * assets/data/biblia_nt.json (the New Testament of the 1988 Synodal Bible,
 * IBMBOR). The daily sync brings both over, so the site and the app read the
 * same pericope on the same day. We have the right to use the 1988 text; its
 * source is shown once, on /despre.
 */
import bible from "../../data/biblia-nt.json";
import data from "../../data/lecturi.json";
import { iso, type Ymd } from "./dates";

type Range = [string, number, number, number, number];
type RawDay = { ap?: Range[]; apCite?: string; ev?: Range[]; evCite?: string; title?: string; none?: string };

export type Lectura = {
  apostol: Range[];
  apostolCite: string | null;
  evanghelie: Range[];
  evanghelieCite: string | null;
  /** "Duminica a II-a după Rusalii". */
  title: string | null;
  /** Why there is no reading that day. */
  none: string | null;
};

export type Verse = { chapter: number; number: number; text: string };

const DAYS = (data as unknown as { days: Record<string, RawDay> }).days;
const BOOKS = new Map(
  (bible as { books: { id: string; chapters: string[][] }[] }).books.map((b) => [b.id, b.chapters]),
);

export const BIBLE_SOURCE: string = (bible as { source: string }).source;
export const LECTURI_YEARS = (data as unknown as { years: [number, number] }).years;

export function lecturaOn(date: Ymd): Lectura | null {
  const d = DAYS[iso(date)];
  if (!d) return null;
  return {
    apostol: d.ap ?? [],
    apostolCite: d.apCite ?? null,
    evanghelie: d.ev ?? [],
    evanghelieCite: d.evCite ?? null,
    title: d.title ?? null,
    none: d.none ?? null,
  };
}

/** The verses of a pericope, in reading order. */
export function textOf(pericope: Range[]): Verse[] {
  const out: Verse[] = [];
  for (const [book, c1, v1, c2, v2] of pericope) {
    const chapters = BOOKS.get(book);
    if (!chapters) continue;
    for (let c = c1; c <= c2 && c <= chapters.length; c++) {
      const ch = chapters[c - 1];
      const from = c === c1 ? v1 : 1;
      const to = c === c2 ? v2 : ch.length;
      for (let v = from; v <= to && v <= ch.length; v++) out.push({ chapter: c, number: v, text: ch[v - 1] });
    }
  }
  return out;
}

/** Every date with an entry, for static pages and the sitemap. */
export const LECTURI_DATES = Object.keys(DAYS);
